+// Consequence of the same bug: declaration emit writes the wrong type.
+// Run: node built/local/tsc.js --strict --declaration --emitDeclarationOnly --outDir /tmp/out repro/declaration_emit.ts
+// 5.6.3 emits `{ prop1: "hello"; }` for r; 5.7.2 and this checkout emit `{ prop1: Wrapper<"hello">; }`.
+type Wrapper<T> = { _type: T }
+function stringWrapper(): Wrapper<string> { return { _type: "" } }
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> { return { _type: obj } }
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>>
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> }
+    : T['_type']
+declare function g<T extends Wrapper<any>>(w: T): Unwrap<T>;
+export const r = g(objWrapper({ prop1: stringWrapper() as Wrapper<"hello"> }));
