--- /dev/null
+++ b/repro/run.js
@@ -0,0 +1,31 @@
+// Usage (from repo root): node repro/run.js [typescript.js path]
+// Prints how the checker displays `Test` for the report's code and for the
+// "assertion on a separate line" control. Exits 1 if the reported symptom shows.
+const path = require("path");
+const ts = require(path.resolve(process.argv[2] || "built/local/typescript.js"));
+
+function show(file) {
+    const program = ts.createProgram([path.join(__dirname, file)], { strict: true, noEmit: true });
+    const checker = program.getTypeChecker();
+    const sf = program.getSourceFile(path.join(__dirname, file));
+    let text;
+    ts.forEachChild(sf, n => {
+        if (ts.isTypeAliasDeclaration(n) && n.name.text === "Test") {
+            const t = checker.getTypeAtLocation(n.name);
+            text = checker.typeToString(t, undefined, ts.TypeFormatFlags.NoTruncation | ts.TypeFormatFlags.InTypeAlias);
+        }
+    });
+    const diags = ts.getPreEmitDiagnostics(program).length;
+    console.log(`${file}: Test = ${text}   (diagnostics: ${diags})`);
+    return text;
+}
+
+console.log("TypeScript", ts.version);
+const actual = show("repro.ts");
+show("repro_separate_line.ts");
+const expected = `{ prop1: "hello"; }`;
+if (actual !== expected) {
+    console.log(`BUG: expected Test = ${expected}`);
+    process.exit(1);
+}
+console.log("OK: matches expected");
